import{_ as r,c as e,o as l,ae as i}from"./chunks/framework.BbFa6TS3.js";const b=JSON.parse('{"title":"工作流","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/workflow.md","filePath":"fe/ai/workflow.md"}'),t={name:"fe/ai/workflow.md"};function o(n,a,h,s,u,p){return l(),e("div",null,a[0]||(a[0]=[i('<h1 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h1><h2 id="n8n" tabindex="-1">n8n <a class="header-anchor" href="#n8n" aria-label="Permalink to &quot;n8n&quot;">​</a></h2><p><a href="https://github.com/n8n-io/n8n" target="_blank" rel="noreferrer">https://github.com/n8n-io/n8n</a></p><p>n8n 是一个工作流自动化平台，它为技术团队提供了代码般的灵活性和无代码般的速度。n8n 拥有 400 多个集成、原生 AI 功能以及公平代码许可证，让您能够构建强大的自动化流程，同时完全掌控您的数据和部署。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><ul><li>节点（Node）：每个节点代表一个功能，比如发送邮件、请求 API、处理数据等。</li><li>工作流（Workflow）：由多个节点组成，定义了自动化的业务流程。</li><li>触发器（Trigger）：工作流的起点，比如定时触发、Webhook、接收邮件等。</li></ul><h3 id="常用功能" tabindex="-1">常用功能 <a class="header-anchor" href="#常用功能" aria-label="Permalink to &quot;常用功能&quot;">​</a></h3><ul><li>内置 400+ 集成：如 Slack、Telegram、GitHub、Notion、MySQL、各类邮件服务等。</li><li>支持自定义代码：可在节点中直接写 JavaScript/Python 处理数据。</li><li>AI 能力：内置 OpenAI、LangChain 等 AI 节点，可实现智能问答、内容生成等。</li><li>可视化调试：每个节点可单步调试，查看输入输出数据。</li></ul><h3 id="自动化场景" tabindex="-1">自动化场景 <a class="header-anchor" href="#自动化场景" aria-label="Permalink to &quot;自动化场景&quot;">​</a></h3><p>场景一：自动同步表单数据到 Google Sheets</p><ol><li>添加触发器节点：选择&quot;Webhook&quot;节点，设置为 POST，n8n 会生成一个 Webhook 地址。</li><li>添加 Google Sheets 节点：搜索并添加&quot;Google Sheets&quot;节点，配置你的 Google 账号，选择&quot;添加行&quot;操作。</li><li>连接节点：将 Webhook 节点输出连接到 Google Sheets 节点输入。</li><li>保存并激活工作流：点击右上角&quot;激活&quot;按钮，n8n 会监听 Webhook 地址，收到数据后自动写入表格。</li></ol><p>场景二：定时抓取新闻并推送到微信/钉钉</p><ol><li>添加定时触发器：选择&quot;Cron&quot;节点，设置定时规则（如每小时）。</li><li>添加 HTTP 请求节点：用于抓取新闻 API。</li><li>添加消息推送节点：比如&quot;DingTalk&quot;或&quot;Wechat&quot;节点，配置推送内容。</li><li>串联节点：按顺序连接，形成完整流程。</li></ol><h3 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h3><ul><li>工作流模板库：<a href="https://n8n.io/workflows" target="_blank" rel="noreferrer">https://n8n.io/workflows</a></li><li>社区教程：<a href="https://community.n8n.io/c/tutorials/28" target="_blank" rel="noreferrer">https://community.n8n.io/c/tutorials/28</a></li><li>集成列表：<a href="https://n8n.io/integrations" target="_blank" rel="noreferrer">https://n8n.io/integrations</a></li></ul><h2 id="dify" tabindex="-1">Dify <a class="header-anchor" href="#dify" aria-label="Permalink to &quot;Dify&quot;">​</a></h2><p><a href="https://dify.ai/zh" target="_blank" rel="noreferrer">https://dify.ai/zh</a></p><p>Dify 是一站式 AI 应用开发与部署平台，帮助团队和开发者从创意到生产，快速打造具备实际价值的 AI Agent。Dify 提供可视化工作流、插件市场、RAG 检索、丰富的集成能力和企业级安全保障，让 AI 应用开发变得高效、灵活且可观测。</p><h3 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h3><ul><li><p><strong>可视化工作流</strong><br> 拖拽式界面，快速搭建灵活高效的 AI 应用和自动化流程，无需复杂编码。</p></li><li><p><strong>插件市场（Marketplace）</strong><br> 丰富的插件生态，涵盖主流大模型（如 OpenAI、Azure OpenAI）、工具、Agent 策略、RAG 组件等，支持一键集成和扩展。</p></li><li><p><strong>RAG Pipeline</strong><br> 支持多数据源接入、数据转化与向量化，助力构建高效的检索增强生成（RAG）应用。</p></li><li><p><strong>多模型无缝接入</strong><br> 兼容全球主流开源与闭源大模型，便于灵活切换和对比模型效果。</p></li><li><p><strong>一键发布与部署</strong><br> 支持多种发布方式，简化后端运维，助力 AI 应用快速上线。</p></li><li><p><strong>可观测性与监控</strong><br> 提供应用运行监控、数据追踪和日志分析，保障生产级应用的稳定性和可维护性。</p></li><li><p><strong>企业级安全</strong><br> 数据加密、权限管理、合规保障等多重安全措施，适配企业级应用需求。</p></li></ul><h3 id="典型应用场景" tabindex="-1">典型应用场景 <a class="header-anchor" href="#典型应用场景" aria-label="Permalink to &quot;典型应用场景&quot;">​</a></h3><ul><li><p><strong>智能问答与知识库</strong><br> 结合 RAG Pipeline，快速搭建企业知识问答、智能客服等场景。</p></li><li><p><strong>Agent 工作流自动化</strong><br> 通过可视化流程，集成多种工具和模型，实现复杂业务自动化。</p></li><li><p><strong>多模态 AI 应用</strong><br> 利用 Marketplace 插件，轻松集成图像、文本、语音等多模态能力。</p></li><li><p><strong>数据接入与处理</strong><br> 支持从多种数据源（如数据库、API、文件等）提取、转化并用于大模型推理。</p></li></ul><h3 id="生态与扩展" tabindex="-1">生态与扩展 <a class="header-anchor" href="#生态与扩展" aria-label="Permalink to &quot;生态与扩展&quot;">​</a></h3><ul><li><p><strong>插件市场</strong><br> 提供 Google Search、Notion、Azure OpenAI 等丰富插件，支持社区共建与自定义扩展。</p></li><li><p><strong>社区与协作</strong><br> 支持工作流的组合、嵌套与分享，促进团队协作和社区共建。</p></li><li><p><strong>持续迭代</strong><br> 产品持续更新，支持最新大模型和 AI 技术，满足不断变化的业务需求。</p></li></ul><h3 id="适用人群" tabindex="-1">适用人群 <a class="header-anchor" href="#适用人群" aria-label="Permalink to &quot;适用人群&quot;">​</a></h3><ul><li>AI 产品经理、开发者</li><li>企业 IT 团队</li><li>希望低门槛构建 AI 应用的业务团队</li><li>需要生产级 AI Agent 的创新型企业</li></ul><h3 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h3><ol><li>访问 <a href="https://dify.ai/zh" target="_blank" rel="noreferrer">Dify 官网</a> 注册账号。</li><li>进入控制台，选择&quot;新建应用&quot;或&quot;新建工作流&quot;。</li><li>通过拖拽节点、配置插件，快速搭建你的 AI 应用。</li><li>一键发布，获取 API 或 Web 端入口，投入实际使用。</li></ol><h3 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h3><ul><li><a href="https://dify.ai/zh" target="_blank" rel="noreferrer">Dify 官网</a></li><li><a href="https://docs.dify.ai/" target="_blank" rel="noreferrer">Dify 文档</a></li><li><a href="https://github.com/langgenius/dify" target="_blank" rel="noreferrer">Dify GitHub</a></li><li><a href="https://dify.ai/zh/blog" target="_blank" rel="noreferrer">Dify 博客</a></li></ul>',30)]))}const g=r(t,[["render",o]]);export{b as __pageData,g as default};
